#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as _dt
import subprocess
import sys
from pathlib import Path
import shutil


VERSION = "0.5.0"

CREATE_B64 = {'frontend/src/components/VisionLabs/ImageProcessing/FilterGuideModal.tsx': '', 'frontend/src/components/VisionLabs/ImageProcessing/operatorGuide.ts': '', 'frontend/tools/generate_llm_context_map.py': '', 'frontend/docs/llm_context/updates/v0050_filter_guide_system_map.md': ''}
REPLACE_B64 = {'frontend/src/components/VisionLabs/ImageProcessing/OperatorLibrary.tsx': {'old': '', 'new': ''}}
README_APPEND = base64.b64decode('').decode("utf-8")

CREATE_FILES = {
    path: base64.b64decode(payload).decode("utf-8")
    for path, payload in CREATE_B64.items()
}

REPLACE_FILES = {
    path: {
        "old": base64.b64decode(payload["old"]).decode("utf-8"),
        "new": base64.b64decode(payload["new"]).decode("utf-8"),
    }
    for path, payload in REPLACE_B64.items()
}


def resolve_roots(frontend_arg, backend_arg):
    cwd = Path.cwd().resolve()

    frontend_candidates = []
    backend_candidates = []

    if frontend_arg:
        frontend_candidates.append(Path(frontend_arg).expanduser().resolve())

    if backend_arg:
        backend_candidates.append(Path(backend_arg).expanduser().resolve())

    frontend_candidates += [
        cwd,
        cwd / "LambdaVisionSuper",
        cwd.parent / "LambdaVisionSuper",
    ]

    backend_candidates += [
        cwd,
        cwd / "LambdaVisionSuperBackEnd",
        cwd.parent / "LambdaVisionSuperBackEnd",
    ]

    frontend = next(
        (
            path
            for path in frontend_candidates
            if (
                path
                / "src/components/VisionLabs/ImageProcessing/OperatorLibrary.tsx"
            ).exists()
            and (
                path
                / "src/components/VisionLabs/ImageProcessing/ZoomPanImageView.tsx"
            ).exists()
            and (
                path / "src/api/imageLabApi.ts"
            ).exists()
        ),
        None,
    )

    backend = next(
        (
            path
            for path in backend_candidates
            if (
                path
                / "app/services/vision_labs/image/runtime.py"
            ).exists()
            and (
                path
                / "app/api/v1/endpoints/image_lab_api.py"
            ).exists()
        ),
        None,
    )

    if frontend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuper frontend. "
            "Use --frontend /path/to/LambdaVisionSuper"
        )

    if backend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuperBackEnd. "
            "Use --backend /path/to/LambdaVisionSuperBackEnd"
        )

    return frontend, backend


def actual_path(frontend, backend, virtual_path):
    prefix, rel = virtual_path.split("/", 1)

    if prefix == "frontend":
        return frontend / rel

    if prefix == "backend":
        return backend / rel

    raise RuntimeError(f"Unknown path prefix: {prefix}")


def backup(frontend, backend, paths):
    stamp = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")

    root = (
        frontend
        / ".lambda_updater_backups"
        / f"filter_guide_system_map_v0050_{stamp}"
    )

    root.mkdir(parents=True, exist_ok=True)

    for path in paths:
        if not path.exists():
            continue

        try:
            rel = path.relative_to(frontend)
            target = root / "frontend" / rel
        except ValueError:
            rel = path.relative_to(backend)
            target = root / "backend" / rel

        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, target)

    return root


def replace_state(path, old, new):
    if not path.exists():
        return "MISSING"

    current = path.read_text(encoding="utf-8")

    if current == new:
        return "OK"

    if current == old:
        return "UPDATE"

    return "CONFLICT"


def create_state(path, desired):
    if not path.exists():
        return "CREATE"

    current = path.read_text(encoding="utf-8")

    if current == desired:
        return "OK"

    return "CONFLICT"


def scan(frontend, backend):
    print("=" * 90)
    print("IMAGE LAB FILTER GUIDE + FULL SYSTEM LLM CONTEXT MAP V0.5.0")
    print("=" * 90)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()

    conflict_count = 0

    for virtual_path, payload in REPLACE_FILES.items():
        path = actual_path(frontend, backend, virtual_path)
        state = replace_state(
            path,
            payload["old"],
            payload["new"],
        )
        print(f"  [{state:8}] {virtual_path}")

        if state in {"CONFLICT", "MISSING"}:
            conflict_count += 1

    for virtual_path, desired in CREATE_FILES.items():
        path = actual_path(frontend, backend, virtual_path)
        state = create_state(path, desired)
        print(f"  [{state:8}] {virtual_path}")

        if state == "CONFLICT":
            conflict_count += 1

    readme = frontend / "docs/llm_context/README.md"
    if not readme.exists():
        print("  [CREATE  ] frontend/docs/llm_context/README.md")
    elif "## Full-system context map" in readme.read_text(encoding="utf-8"):
        print("  [OK      ] frontend/docs/llm_context/README.md")
    else:
        print("  [APPEND  ] frontend/docs/llm_context/README.md")

    system_map = frontend / "docs/llm_context/SYSTEM_FILE_MAP.md"
    print(
        f"  [{'REFRESH' if system_map.exists() else 'GENERATE':8}] "
        "frontend/docs/llm_context/SYSTEM_FILE_MAP.md"
    )

    print()
    print("Features:")
    print("  - (i) guide button for every Image LAB filter/operator.")
    print("  - Three-column Guide | Preview | Parameters standalone playground.")
    print("  - Independent temporary Image LAB session; current stack is untouched.")
    print("  - Manual Run Test behavior; parameter edits do not auto-execute.")
    print("  - Explicit BinaryMask input adapter for mask-only operators.")
    print("  - Dynamic category + parameter guidance with special operator notes.")
    print("  - Full FE+BE source inventory generator for future LLM context handoff.")

    if conflict_count:
        print()
        print(
            f"[WARN] {conflict_count} conflict(s) detected. "
            "apply will stop rather than overwrite local modifications."
        )

    return 0


def preflight(frontend, backend):
    errors = []

    for virtual_path, payload in REPLACE_FILES.items():
        path = actual_path(frontend, backend, virtual_path)
        state = replace_state(
            path,
            payload["old"],
            payload["new"],
        )

        if state not in {"OK", "UPDATE"}:
            errors.append(
                f"{virtual_path}: expected known baseline, found {state}"
            )

    for virtual_path, desired in CREATE_FILES.items():
        path = actual_path(frontend, backend, virtual_path)
        state = create_state(path, desired)

        if state not in {"OK", "CREATE"}:
            errors.append(
                f"{virtual_path}: existing file differs from v0.5.0 target"
            )

    if errors:
        raise RuntimeError(
            "Safe update stopped because local changes/conflicts were found:\n  - "
            + "\n  - ".join(errors)
        )


def ensure_readme(frontend):
    path = frontend / "docs/llm_context/README.md"
    path.parent.mkdir(parents=True, exist_ok=True)

    if not path.exists():
        path.write_text(
            "# Lambda Vision LLM Context\n\n"
            "This directory contains structural snapshots and update notes "
            "designed to make future LLM-assisted code changes efficient.\n"
            + README_APPEND,
            encoding="utf-8",
        )
        return "CREATE"

    text = path.read_text(encoding="utf-8")

    if "## Full-system context map" in text:
        return "OK"

    separator = "" if text.endswith("\n") else "\n"
    path.write_text(
        text + separator + README_APPEND,
        encoding="utf-8",
    )

    return "APPEND"


def generate_system_map(frontend, backend):
    tool = frontend / "tools/generate_llm_context_map.py"
    output = frontend / "docs/llm_context/SYSTEM_FILE_MAP.md"

    result = subprocess.run(
        [
            sys.executable,
            str(tool),
            "--frontend",
            str(frontend),
            "--backend",
            str(backend),
            "--output",
            str(output),
        ],
        cwd=str(frontend),
        text=True,
        capture_output=True,
    )

    if result.returncode != 0:
        raise RuntimeError(
            "System file map generation failed:\n"
            + (result.stdout + "\n" + result.stderr).strip()
        )

    print(result.stdout.strip())


def apply(frontend, backend):
    preflight(frontend, backend)

    targets = []

    for virtual_path in list(REPLACE_FILES) + list(CREATE_FILES):
        targets.append(actual_path(frontend, backend, virtual_path))

    readme = frontend / "docs/llm_context/README.md"
    system_map = frontend / "docs/llm_context/SYSTEM_FILE_MAP.md"

    targets.extend([readme, system_map])

    backup_root = backup(
        frontend,
        backend,
        targets,
    )

    for virtual_path, payload in REPLACE_FILES.items():
        path = actual_path(frontend, backend, virtual_path)

        if path.read_text(encoding="utf-8") != payload["new"]:
            path.write_text(
                payload["new"],
                encoding="utf-8",
            )
            print(f"[WRITE] {virtual_path}")

    for virtual_path, desired in CREATE_FILES.items():
        path = actual_path(frontend, backend, virtual_path)
        path.parent.mkdir(parents=True, exist_ok=True)

        if not path.exists() or path.read_text(encoding="utf-8") != desired:
            path.write_text(
                desired,
                encoding="utf-8",
            )
            print(f"[WRITE] {virtual_path}")

    readme_action = ensure_readme(frontend)
    print(
        f"[{readme_action}] frontend/docs/llm_context/README.md"
    )

    generate_system_map(frontend, backend)

    print(f"[OK] Backup: {backup_root}")
    print("Run verify next.")
    return 0


def typescript_check(frontend):
    files = [
        frontend
        / "src/components/VisionLabs/ImageProcessing/OperatorLibrary.tsx",
        frontend
        / "src/components/VisionLabs/ImageProcessing/FilterGuideModal.tsx",
        frontend
        / "src/components/VisionLabs/ImageProcessing/operatorGuide.ts",
    ]

    node_code = r"""
const fs = require("fs");
const ts = require("typescript");

let failed = false;

for (const file of process.argv.slice(1)) {
  const source = fs.readFileSync(file, "utf8");

  const result = ts.transpileModule(source, {
    fileName: file,
    reportDiagnostics: true,
    compilerOptions: {
      jsx: ts.JsxEmit.ReactJSX,
      target: ts.ScriptTarget.ES2020,
      module: ts.ModuleKind.ESNext,
    },
  });

  const errors = (result.diagnostics || []).filter(
    (item) => item.category === ts.DiagnosticCategory.Error,
  );

  if (errors.length) {
    failed = true;
    console.error("TYPE_SCRIPT_ERROR", file);

    for (const item of errors) {
      console.error(
        ts.flattenDiagnosticMessageText(item.messageText, "\n"),
      );
    }
  }
}

process.exit(failed ? 1 : 0);
"""

    return subprocess.run(
        ["node", "-e", node_code, *[str(path) for path in files]],
        cwd=str(frontend),
        text=True,
        capture_output=True,
    )


def verify(frontend, backend, skip_build=False):
    print("=" * 90)
    print("VERIFY IMAGE LAB FILTER GUIDE + FULL SYSTEM LLM CONTEXT MAP V0.5.0")
    print("=" * 90)

    failures = 0

    operator_library = (
        frontend
        / "src/components/VisionLabs/ImageProcessing/OperatorLibrary.tsx"
    ).read_text(encoding="utf-8")

    modal = (
        frontend
        / "src/components/VisionLabs/ImageProcessing/FilterGuideModal.tsx"
    ).read_text(encoding="utf-8")

    guide = (
        frontend
        / "src/components/VisionLabs/ImageProcessing/operatorGuide.ts"
    ).read_text(encoding="utf-8")

    checks = [
        (
            "Operator Library has per-filter guide button",
            "setGuideOperator(operator)" in operator_library
            and "CircleHelp" in operator_library,
        ),
        (
            "Guide modal uses isolated temporary Image LAB session",
            "ImageLabAPI.createSession()" in modal
            and "ImageLabAPI.closeSession" in modal,
        ),
        (
            "Guide modal never mutates processing stack",
            "onAdd" not in modal
            and "ProcessingStack" not in modal,
        ),
        (
            "Standalone test is explicit/manual",
            "Run Test" in modal
            and "Changes are local until Run Test." in modal,
        ),
        (
            "BinaryMask playground input adapter is explicit",
            "Playground mask adapter" in modal
            and "image.threshold.binary" in modal,
        ),
        (
            "Numeric enum choice typing is preserved",
            "choices[Number(event.target.value)]" in modal,
        ),
        (
            "Guide has category and parameter-specific help",
            "categoryGuides" in guide
            and "specialGuides" in guide
            and "parameterTip" in guide,
        ),
        (
            "Full-system inventory generator installed",
            (
                frontend / "tools/generate_llm_context_map.py"
            ).exists(),
        ),
        (
            "Per-update context note installed",
            (
                frontend
                / "docs/llm_context/updates/v0050_filter_guide_system_map.md"
            ).exists(),
        ),
    ]

    for label, ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        failures += 0 if ok else 1

    tool = frontend / "tools/generate_llm_context_map.py"

    try:
        compile(
            tool.read_text(encoding="utf-8"),
            str(tool),
            "exec",
        )
        print("[OK] Context generator Python syntax")
    except Exception as exc:
        print(f"[FAIL] Context generator Python syntax: {exc}")
        failures += 1

    with subprocess.Popen(
        [
            sys.executable,
            str(tool),
            "--frontend",
            str(frontend),
            "--backend",
            str(backend),
            "--output",
            str(frontend / "docs/llm_context/SYSTEM_FILE_MAP.md"),
        ],
        cwd=str(frontend),
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    ) as process:
        stdout, stderr = process.communicate()

        if process.returncode == 0:
            print("[OK] Full-system context map regeneration")
            if stdout.strip():
                print(stdout.strip())
        else:
            print("[FAIL] Full-system context map regeneration")
            print((stdout + "\n" + stderr).strip())
            failures += 1

    system_map = frontend / "docs/llm_context/SYSTEM_FILE_MAP.md"

    if system_map.exists():
        text = system_map.read_text(encoding="utf-8")
        inventory_ok = (
            "# Lambda Vision — Full System File Map" in text
            and "## Full file inventory" in text
            and "FE:" in text
            and "BE:" in text
        )
    else:
        inventory_ok = False

    print(
        f"[{'OK' if inventory_ok else 'FAIL'}] "
        "SYSTEM_FILE_MAP.md contains FE+BE full inventory"
    )

    failures += 0 if inventory_ok else 1

    ts = typescript_check(frontend)

    if ts.returncode == 0:
        print("[OK] TypeScript syntax/transpile check")
    else:
        combined = (ts.stdout + "\n" + ts.stderr).strip()

        if "Cannot find module 'typescript'" in combined:
            print(
                "[SKIP] TypeScript transpile check: "
                "typescript module unavailable to node"
            )
        else:
            print("[FAIL] TypeScript syntax/transpile check")
            print(combined)
            failures += 1

    if (
        not skip_build
        and (frontend / "package.json").exists()
        and (frontend / "node_modules").exists()
    ):
        build = subprocess.run(
            ["npm", "run", "build"],
            cwd=str(frontend),
        )

        if build.returncode == 0:
            print("[OK] Frontend npm build")
        else:
            print("[FAIL] Frontend npm build")
            failures += 1
    else:
        print("[SKIP] Frontend npm build")

    if failures:
        print(
            f"[FAIL] Verification completed with {failures} issue(s)."
        )
        return 1

    print(
        "[OK] Image LAB Filter Guide + System Context Map v0.5.0 verified."
    )
    return 0


def main():
    parser = argparse.ArgumentParser()

    parser.add_argument(
        "command",
        choices=["scan", "apply", "verify", "context-map"],
    )

    parser.add_argument("--frontend")
    parser.add_argument("--backend")
    parser.add_argument(
        "--skip-build",
        action="store_true",
    )

    args = parser.parse_args()

    try:
        frontend, backend = resolve_roots(
            args.frontend,
            args.backend,
        )

        if args.command == "scan":
            return scan(frontend, backend)

        if args.command == "apply":
            return apply(frontend, backend)

        if args.command == "context-map":
            generate_system_map(frontend, backend)
            return 0

        return verify(
            frontend,
            backend,
            skip_build=args.skip_build,
        )

    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
